record.field:
website = env.ref('hair_salon.website_industry')
to_deactivate = [ 'website.footer_custom', 'website.header_search_box', 'website.header_text_element', 'website.template_footer_mega', 'website.homepage', 'website.contactus', ] to_activate = [ 'website.footer_no_copyright', 'website.header_call_to_action', 'website.template_footer_centered', 'website.template_footer_slideout', ]
ctx = {'website_id': website.id}
for xml_id in to_deactivate: env.ref(xml_id).with_context(**ctx).write({'active': False}) for xml_id in to_activate: env.ref(xml_id).with_context(**ctx).write({'active': True})
